INSERT INTO `v1_7921e1fb548ae11b63587f3cfc2947d2962bf3205f5cfc26a665a02f2a678add` VALUES (3, "スタンダードコレクション", "スタンダードコレクションではポスターやペナントなど\n部屋に飾れる定番グッズが盛りだくさん！\nあなたの部屋をカルミナで彩ろう！", 1, "1回メダル{0}枚！\n定番グッズであなたの部屋をカルミナで彩ろう！", 1);
INSERT INTO `v1_7921e1fb548ae11b63587f3cfc2947d2962bf3205f5cfc26a665a02f2a678add` VALUES (10, "プレミアムコレクション", "プレミアムコレクションではサイン色紙や\nブロマイドなど、★★以上のグッズが盛りだくさん！\nレアグッズをたくさんゲットしよう！", 1, "1回メダル{0}枚！\nメンバー直筆サイン色紙など、★★以上のグッズを確定でゲット！", 2);
INSERT INTO `v1_7921e1fb548ae11b63587f3cfc2947d2962bf3205f5cfc26a665a02f2a678add` VALUES (3, "フェスコレクション", "フェスコレクションではカルミナサマーライブで\n大活躍するグッズが勢ぞろい！\nゲットしたグッズを片手に、いざライブ会場へ！", 1, "1回メダル{0}枚！\nカルミナライブに参加する際のマストアイテムをゲットしよう！", 3);
